//! Minimal naive date/time handling, modelled after the behaviour of the
//! formats used by the time tracker ("%Y-%m-%d", "%H:%M", ...).

use std::time::{SystemTime, UNIX_EPOCH};

pub const MIN_YEAR: i64 = -262143;
pub const MAX_YEAR: i64 = 262142;

pub const NANOS_PER_SEC: i128 = 1_000_000_000;

/// A duration expressed in nanoseconds.
pub type Duration = i128;

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let m = m as i64;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn fmt_year(y: i64) -> String {
    if (0..10000).contains(&y) {
        format!("{:04}", y)
    } else {
        format!("{:+05}", y)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct Date {
    pub days: i64,
}

impl Date {
    pub fn from_ymd(y: i64, m: u32, d: u32) -> Option<Date> {
        if !(MIN_YEAR..=MAX_YEAR).contains(&y) || !(1..=12).contains(&m) {
            return None;
        }
        if d < 1 || d > days_in_month(y, m) {
            return None;
        }
        Some(Date {
            days: days_from_civil(y, m, d),
        })
    }

    pub fn ymd(&self) -> (i64, u32, u32) {
        civil_from_days(self.days)
    }

    /// 0 = Monday ... 6 = Sunday
    pub fn weekday_from_monday(&self) -> i64 {
        (self.days + 3).rem_euclid(7)
    }

    pub fn add_days(&self, n: i64) -> Date {
        Date { days: self.days + n }
    }

    pub fn first_of_month(&self) -> Date {
        let (y, m, _) = self.ymd();
        Date {
            days: days_from_civil(y, m, 1),
        }
    }

    pub fn format(&self) -> String {
        let (y, m, d) = self.ymd();
        format!("{}-{:02}-{:02}", fmt_year(y), m, d)
    }

    pub fn and_hms(&self, h: u32, m: u32, s: u32) -> DateTime {
        DateTime {
            secs: self.days * 86400 + (h as i64) * 3600 + (m as i64) * 60 + s as i64,
            nanos: 0,
        }
    }
}

/// A naive (time zone less) date time.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct DateTime {
    pub secs: i64,
    pub nanos: u32,
}

impl DateTime {
    pub fn date(&self) -> Date {
        Date {
            days: self.secs.div_euclid(86400),
        }
    }

    pub fn hms(&self) -> (u32, u32, u32) {
        let s = self.secs.rem_euclid(86400);
        ((s / 3600) as u32, ((s / 60) % 60) as u32, (s % 60) as u32)
    }

    pub fn format_time(&self) -> String {
        let (h, m, _) = self.hms();
        format!("{:02}:{:02}", h, m)
    }

    pub fn format(&self) -> String {
        format!("{} {}", self.date().format(), self.format_time())
    }

    pub fn since(&self, other: &DateTime) -> Duration {
        (self.secs as i128 - other.secs as i128) * NANOS_PER_SEC + (self.nanos as i128 - other.nanos as i128)
    }

    pub fn from_timestamp(secs: i64) -> DateTime {
        DateTime { secs, nanos: 0 }
    }
}

#[repr(C)]
struct Tm {
    tm_sec: i32,
    tm_min: i32,
    tm_hour: i32,
    tm_mday: i32,
    tm_mon: i32,
    tm_year: i32,
    tm_wday: i32,
    tm_yday: i32,
    tm_isdst: i32,
    tm_gmtoff: i64,
    tm_zone: *const u8,
}

extern "C" {
    fn localtime_r(t: *const i64, tm: *mut Tm) -> *mut Tm;
    fn tzset();
}

fn local_offset(t: i64) -> i64 {
    unsafe {
        tzset();
        let mut tm: Tm = std::mem::zeroed();
        let tt: i64 = t;
        if localtime_r(&tt, &mut tm).is_null() {
            0
        } else {
            tm.tm_gmtoff
        }
    }
}

/// Current local time as naive date time.
pub fn now() -> DateTime {
    let d = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| std::time::Duration::from_secs(0));
    let secs = d.as_secs() as i64;
    let off = local_offset(secs);
    DateTime {
        secs: secs + off,
        nanos: d.subsec_nanos(),
    }
}

pub fn today() -> Date {
    now().date()
}

// ---------------------------------------------------------------------------
// Parsing

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseError {
    OutOfRange,
    #[allow(dead_code)]
    Impossible,
    NotEnough,
    Invalid,
    TooShort,
    TooLong,
}

impl ParseError {
    pub fn message(&self) -> &'static str {
        match self {
            ParseError::OutOfRange => "input is out of range",
            ParseError::Impossible => "no possible date and time matching input",
            ParseError::NotEnough => "input is not enough for unique date and time",
            ParseError::Invalid => "input contains invalid characters",
            ParseError::TooShort => "premature end of input",
            ParseError::TooLong => "trailing input",
        }
    }
}

#[derive(Clone, Copy)]
enum Item {
    Lit(&'static str),
    Space,
    Year,
    Month,
    Day,
    Hour,
    Minute,
    Second,
}

#[derive(Default)]
struct Parsed {
    year: Option<i64>,
    month: Option<i64>,
    day: Option<i64>,
    hour: Option<i64>,
    minute: Option<i64>,
    second: Option<i64>,
}

fn scan_number(s: &str, min: usize, max: usize) -> Result<(&str, i64), ParseError> {
    let bytes = s.as_bytes();
    if bytes.len() < min {
        return Err(ParseError::TooShort);
    }
    let mut n: i64 = 0;
    for (i, &c) in bytes.iter().take(max).enumerate() {
        if !c.is_ascii_digit() {
            if i < min {
                return Err(ParseError::Invalid);
            } else {
                return Ok((&s[i..], n));
            }
        }
        n = match n.checked_mul(10).and_then(|n| n.checked_add((c - b'0') as i64)) {
            Some(n) => n,
            None => return Err(ParseError::OutOfRange),
        };
    }
    Ok((&s[std::cmp::min(max, bytes.len())..], n))
}

fn parse_items(mut s: &str, items: &[Item]) -> Result<Parsed, ParseError> {
    let mut p = Parsed::default();
    for item in items {
        match *item {
            Item::Lit(lit) => {
                if s.len() < lit.len() {
                    return Err(ParseError::TooShort);
                }
                if !s.starts_with(lit) {
                    return Err(ParseError::Invalid);
                }
                s = &s[lit.len()..];
            }
            Item::Space => {
                s = s.trim_start();
            }
            num => {
                s = s.trim_start();
                let v;
                if let Item::Year = num {
                    if let Some(rest) = s.strip_prefix('-') {
                        let (r, x) = scan_number(rest, 1, usize::MAX)?;
                        s = r;
                        v = -x;
                    } else if let Some(rest) = s.strip_prefix('+') {
                        let (r, x) = scan_number(rest, 1, usize::MAX)?;
                        s = r;
                        v = x;
                    } else {
                        let (r, x) = scan_number(s, 1, 4)?;
                        s = r;
                        v = x;
                    }
                } else {
                    let (r, x) = scan_number(s, 1, 2)?;
                    s = r;
                    v = x;
                }
                match num {
                    Item::Year => {
                        if i32::try_from(v).is_err() {
                            return Err(ParseError::OutOfRange);
                        }
                        p.year = Some(v);
                    }
                    Item::Month => {
                        if !(1..=12).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.month = Some(v);
                    }
                    Item::Day => {
                        if !(1..=31).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.day = Some(v);
                    }
                    Item::Hour => {
                        if !(0..=23).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.hour = Some(v);
                    }
                    Item::Minute => {
                        if !(0..=59).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.minute = Some(v);
                    }
                    Item::Second => {
                        if !(0..=60).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.second = Some(v);
                    }
                    _ => {}
                }
            }
        }
    }
    if !s.is_empty() {
        return Err(ParseError::TooLong);
    }
    Ok(p)
}

fn to_date(p: &Parsed) -> Result<Date, ParseError> {
    match (p.year, p.month, p.day) {
        (Some(y), Some(m), Some(d)) => Date::from_ymd(y, m as u32, d as u32).ok_or(ParseError::OutOfRange),
        _ => Err(ParseError::NotEnough),
    }
}

/// returns seconds of day
fn to_time(p: &Parsed) -> Result<i64, ParseError> {
    let h = p.hour.ok_or(ParseError::NotEnough)?;
    let m = p.minute.ok_or(ParseError::NotEnough)?;
    let s = p.second.unwrap_or(0);
    // a leap second (60) is represented as 59 seconds plus one extra second of nanos;
    // for our purposes treating it as second 59 is sufficient.
    let s = if s == 60 { 59 } else { s };
    Ok(h * 3600 + m * 60 + s)
}

pub fn parse_date(s: &str) -> Result<Date, ParseError> {
    let p = parse_items(s, &[Item::Year, Item::Lit("-"), Item::Month, Item::Lit("-"), Item::Day])?;
    to_date(&p)
}

/// Parses "%H:%M" and returns the seconds of the day.
pub fn parse_time(s: &str) -> Result<i64, ParseError> {
    let p = parse_items(s, &[Item::Hour, Item::Lit(":"), Item::Minute])?;
    to_time(&p)
}

pub fn parse_datetime_minutes(s: &str) -> Result<DateTime, ParseError> {
    let p = parse_items(
        s,
        &[
            Item::Year,
            Item::Lit("-"),
            Item::Month,
            Item::Lit("-"),
            Item::Day,
            Item::Space,
            Item::Hour,
            Item::Lit(":"),
            Item::Minute,
        ],
    )?;
    let d = to_date(&p)?;
    let t = to_time(&p)?;
    Ok(DateTime {
        secs: d.days * 86400 + t,
        nanos: 0,
    })
}

pub fn parse_datetime_seconds(s: &str) -> Result<DateTime, ParseError> {
    let p = parse_items(
        s,
        &[
            Item::Year,
            Item::Lit("-"),
            Item::Month,
            Item::Lit("-"),
            Item::Day,
            Item::Space,
            Item::Hour,
            Item::Lit(":"),
            Item::Minute,
            Item::Lit(":"),
            Item::Second,
        ],
    )?;
    let d = to_date(&p)?;
    let t = to_time(&p)?;
    Ok(DateTime {
        secs: d.days * 86400 + t,
        nanos: 0,
    })
}

// ---------------------------------------------------------------------------
// Durations

pub fn num_seconds(d: Duration) -> i128 {
    d / NANOS_PER_SEC
}

pub fn format_duration(d: Duration) -> String {
    let secs = num_seconds(d);
    let hours = secs / 3600;
    let minutes = secs / 60;
    let mut s = String::new();
    if hours > 0 {
        s.push_str(&format!("{}h ", hours));
    }
    if minutes > 0 {
        s.push_str(&format!("{:0>2}m", minutes % 60));
    } else {
        s.push_str("<1m");
    }
    s
}

/// Rounds a date time to the nearest multiple of `round_secs` seconds since the epoch.
pub fn round_datetime(dt: &DateTime, round_secs: i64) -> DateTime {
    let ts = dt.secs as f64;
    let r = round_secs as f64;
    let rounded = ((ts / r).round() * r) as i64;
    DateTime::from_timestamp(rounded)
}
