    Year,
    Month,
    Day,
    Hour,
    Minute,
    Second,
}

#[derive(Default)]
struct Parsed {
    year: Option<i64>,
    month: Option<i64>,
    day: Option<i64>,
    hour: Option<i64>,
    minute: Option<i64>,
    second: Option<i64>,
}

fn scan_number(s: &str, min: usize, max: usize) -> Result<(&str, i64), ParseError> {
    let bytes = s.as_bytes();
    if bytes.len() < min {
        return Err(ParseError::TooShort);
    }
    let mut n: i64 = 0;
    for (i, &c) in bytes.iter().take(max).enumerate() {
        if !c.is_ascii_digit() {
            if i < min {
                return Err(ParseError::Invalid);
            } else {
                return Ok((&s[i..], n));
            }
        }
        n = match n.checked_mul(10).and_then(|n| n.checked_add((c - b'0') as i64)) {
            Some(n) => n,
            None => return Err(ParseError::OutOfRange),
        };
    }
    Ok((&s[std::cmp::min(max, bytes.len())..], n))
}

fn parse_items(mut s: &str, items: &[Item]) -> Result<Parsed, ParseError> {
    let mut p = Parsed::default();
    for item in items {
        match *item {
            Item::Lit(lit) => {
                if s.len() < lit.len() {
                    return Err(ParseError::TooShort);
                }
                if !s.starts_with(lit) {
                    return Err(ParseError::Invalid);
                }
                s = &s[lit.len()..];
            }
            Item::Space => {
                s = s.trim_start();
            }
            num => {
                s = s.trim_start();
                let v;
                if let Item::Year = num {
                    if let Some(rest) = s.strip_prefix('-') {
                        let (r, x) = scan_number(rest, 1, usize::MAX)?;
                        s = r;
                        v = -x;
                    } else if let Some(rest) = s.strip_prefix('+') {
                        let (r, x) = scan_number(rest, 1, usize::MAX)?;
                        s = r;
                        v = x;
                    } else {
                        let (r, x) = scan_number(s, 1, 4)?;
                        s = r;
                        v = x;
                    }
                } else {
                    let (r, x) = scan_number(s, 1, 2)?;
                    s = r;
                    v = x;
                }
                match num {
                    Item::Year => {
                        if i32::try_from(v).is_err() {
                            return Err(ParseError::OutOfRange);
                        }
                        p.year = Some(v);
                    }
                    Item::Month => {
                        if !(1..=12).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.month = Some(v);
                    }
                    Item::Day => {
                        if !(1..=31).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.day = Some(v);
                    }
                    Item::Hour => {
                        if !(0..=23).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.hour = Some(v);
                    }
                    Item::Minute => {
                        if !(0..=59).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.minute = Some(v);
                    }
                    Item::Second => {
                        if !(0..=60).contains(&v) {
                            return Err(ParseError::OutOfRange);
                        }
                        p.second = Some(v);
                    }
                    _ => {}
                }
            }
        }
    }
    if !s.is_empty() {
        return Err(ParseError::TooLong);
    }
    Ok(p)
}

fn to_date(p: &Parsed) -> Result<Date, ParseError> {
    match (p.year, p.month, p.day) {
        (Some(y), Some(m), Some(d)) => Date::from_ymd(y, m as u32, d as u32).ok_or(ParseError::OutOfRange),
        _ => Err(ParseError::NotEnough),
    }
}

/// returns seconds of day
fn to_time(p: &Parsed) -> Result<i64, ParseError> {
    let h = p.hour.ok_or(ParseError::NotEnough)?;
    let m = p.minute.ok_or(ParseError::NotEnough)?;
    let s = p.second.unwrap_or(0);
    // a leap second (60) is represented as 59 seconds plus one extra second of nanos;
    // for our purposes treating it as second 59 is sufficient.
    let s = if s == 60 { 59 } else { s };
    Ok(h * 3600 + m * 60 + s)
}

pub fn parse_date(s: &str) -> Result<Date, ParseError> {
    let p = parse_items(s, &[Item::Year, Item::Lit("-"), Item::Month, Item::Lit("-"), Item::Day])?;
    to_date(&p)
}

/// Parses "%H:%M" and returns the seconds of the day.
pub fn parse_time(s: &str) -> Result<i64, ParseError> {
    let p = parse_items(s, &[Item::Hour, Item::Lit(":"), Item::Minute])?;
    to_time(&p)
}

pub fn parse_datetime_minutes(s: &str) -> Result<DateTime, ParseError> {
    let p = parse_items(
        s,
        &[
            Item::Year,
            Item::Lit("-"),
            Item::Month,
            Item::Lit("-"),
            Item::Day,
            Item::Space,
            Item::Hour,
            Item::Lit(":"),
            Item::Minute,
        ],
    )?;
    let d = to_date(&p)?;
    let t = to_time(&p)?;
    Ok(DateTime {
        secs: d.days * 86400 + t,
        nanos: 0,
    })
}

pub fn parse_datetime_seconds(s: &str) -> Result<DateTime, ParseError> {
    let p = parse_items(
        s,
        &[
            Item::Year,
            Item::Lit("-"),
            Item::Month,
            Item::Lit("-"),
            Item::Day,
            Item::Space,
            Item::Hour,
            Item::Lit(":"),
            Item::Minute,
            Item::Lit(":"),
            Item::Second,
        ],
    )?;
    let d = to_date(&p)?;
    let t = to_time(&p)?;
    Ok(DateTime {
        secs: d.days * 86400 + t,
        nanos: 0,
    })
}

// ---------------------------------------------------------------------------
// Durations

pub fn num_seconds(d: Duration) -> i128 {
    d / NANOS_PER_SEC
}

pub fn format_duration(d: Duration) -> String {
    let secs = num_seconds(d);
    let hours = secs / 3600;
    let minutes = secs / 60;
    let mut s = String::new();
    if hours > 0 {
        s.push_str(&format!("{}h ", hours));
    }
    if minutes > 0 {
        s.push_str(&format!("{:0>2}m", minutes % 60));
    } else {
        s.push_str("<1m");
    }
    s
}

/// Rounds a date time to the nearest multiple of `round_secs` seconds since the epoch.
pub fn round_datetime(dt: &DateTime, round_secs: i64) -> DateTime {
    let ts = dt.secs as f64;
    let r = round_secs as f64;
    let rounded = ((ts / r).round() * r) as i64;
    DateTime::from_timestamp(rounded)
}
EOF
