//! Activities and the bartib log file format.

use crate::time::{self, DateTime, Duration};
use std::fs::File;
use std::io::{BufRead, BufReader, Write};

#[derive(Clone, Debug)]
pub struct Activity {
    pub start: DateTime,
    pub end: Option<DateTime>,
    pub project: String,
    pub description: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ActivityError {
    General,
    DateTime,
}

impl ActivityError {
    pub fn message(&self) -> &'static str {
        match self {
            ActivityError::General => "could not parse activity",
            ActivityError::DateTime => "could not parse date or time of activity",
        }
    }
}

impl Activity {
    pub fn start(project: &str, description: &str, time: Option<DateTime>) -> Activity {
        Activity {
            start: time.unwrap_or_else(time::now),
            end: None,
            project: project.to_string(),
            description: description.to_string(),
        }
    }

    pub fn stop(&mut self, time: Option<DateTime>) {
        self.end = Some(time.unwrap_or_else(time::now));
    }

    pub fn is_stopped(&self) -> bool {
        self.end.is_some()
    }

    pub fn get_duration(&self) -> Duration {
        match self.end {
            Some(end) => end.since(&self.start),
            None => time::now().since(&self.start),
        }
    }

    pub fn serialize(&self) -> String {
        let project = escape_special_chars(&self.project);
        let description = escape_special_chars(&self.description);
        match self.end {
            None => format!("{} | {} | {}", self.start.format(), project, description),
            Some(end) => format!(
                "{} - {} | {} | {}",
                self.start.format(),
                end.format(),
                project,
                description
            ),
        }
    }
}

fn escape_special_chars(s: &str) -> String {
    s.replace('\\', "\\\\").replace('|', "\\|")
}

fn split_with_escaped_delimiter(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut escaped = false;
    for c in s.chars() {
        if escaped {
            current.push(c);
            escaped = false;
        } else if c == '\\' {
            escaped = true;
        } else if c == '|' {
            parts.push(std::mem::take(&mut current));
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }
    parts
}

fn parse_timestamp(s: &str) -> Result<DateTime, ActivityError> {
    match time::parse_datetime_minutes(s) {
        Ok(dt) => Ok(dt),
        Err(_) => match time::parse_datetime_seconds(s) {
            Ok(dt) => {
                eprintln!("WARNING: Bartib log encountered timestamps with minute precision.");
                eprintln!("This version of Bartib has been compiled with second precision");
                Ok(time::round_datetime(&dt, 60))
            }
            Err(_) => Err(ActivityError::DateTime),
        },
    }
}

pub fn parse_activity(line: &str) -> Result<Activity, ActivityError> {
    let parts = split_with_escaped_delimiter(line);
    if parts.len() < 2 {
        return Err(ActivityError::General);
    }
    let time_parts: Vec<&str> = parts[0].split(" - ").collect();
    let start = parse_timestamp(time_parts[0].trim())?;
    let end = if time_parts.len() > 1 {
        Some(parse_timestamp(time_parts[1].trim())?)
    } else {
        None
    };
    let project = parts[1].trim().to_string();
    let description = if parts.len() > 2 {
        parts[2].trim().to_string()
    } else {
        String::new()
    };
    Ok(Activity {
        start,
        end,
        project,
        description,
    })
}

pub struct Line {
    pub number: usize,
    pub text: String,
    pub activity: Result<Activity, ActivityError>,
    pub changed: bool,
}

impl Line {
    pub fn new_activity(activity: Activity, number: usize) -> Line {
        Line {
            number,
            text: String::new(),
            activity: Ok(activity),
            changed: true,
        }
    }
}

pub struct IoError {
    pub context: String,
    pub error: std::io::Error,
}

pub fn read_file(path: &str) -> Result<Vec<Line>, IoError> {
    let file = File::open(path).map_err(|e| IoError {
        context: format!("Could not read from file: {}", path),
        error: e,
    })?;
    let reader = BufReader::new(file);
    let mut lines = Vec::new();
    for (i, l) in reader.lines().map_while(Result::ok).enumerate() {
        let text = l.trim().to_string();
        let activity = parse_activity(&text);
        lines.push(Line {
            number: i + 1,
            text,
            activity,
            changed: false,
        });
    }
    Ok(lines)
}

pub fn write_file(path: &str, lines: &[Line]) -> Result<(), IoError> {
    let ctx = || format!("Could not write to file: {}", path);
    let mut file = File::create(path).map_err(|e| IoError {
        context: ctx(),
        error: e,
    })?;
    let mut out = String::new();
    for line in lines {
        match (&line.activity, line.changed) {
            (Ok(a), true) => {
                out.push_str(&a.serialize());
            }
            _ => {
                out.push_str(&line.text);
            }
        }
        out.push('\n');
    }
    file.write_all(out.as_bytes()).map_err(|e| IoError {
        context: ctx(),
        error: e,
    })?;
    Ok(())
}

/// Returns all successfully parsed activities, printing a warning for every
/// line that could not be parsed.
pub fn get_activities(lines: &[Line]) -> Vec<(usize, &Activity)> {
    let mut result = Vec::new();
    for line in lines {
        match &line.activity {
            Ok(a) => result.push((line.number, a)),
            Err(_) => println!(
                "Warning: Ignoring line {}. Please see `bartib check` for further information",
                line.number
            ),
        }
    }
    result
}

pub fn get_activities_silent(lines: &[Line]) -> Vec<(usize, &Activity)> {
    lines
        .iter()
        .filter_map(|l| l.activity.as_ref().ok().map(|a| (l.number, a)))
        .collect()
}

/// Distinct (description, project) pairs, most recent first.
pub fn get_descriptions_and_projects(lines: &[Line]) -> Vec<(String, String)> {
    let mut activities: Vec<&Activity> = get_activities(lines).into_iter().map(|(_, a)| a).collect();
    activities.sort_by_key(|a| a.start);
    let mut result: Vec<(String, String)> = Vec::new();
    for a in activities.iter().rev() {
        if !result
            .iter()
            .any(|(d, p)| *d == a.description && *p == a.project)
        {
            result.push((a.description.clone(), a.project.clone()));
        }
    }
    result
}
