//! Simple table output (column widths computed from the content).

pub const NBSP: char = '\u{a0}';

#[derive(Clone, Copy)]
pub enum Style {
    Green,
    Yellow,
}

impl Style {
    fn prefix(&self) -> &'static str {
        match self {
            Style::Green => "\x1b[32m",
            Style::Yellow => "\x1b[33m",
        }
    }
}

pub struct Row {
    pub cells: Vec<String>,
    pub style: Option<Style>,
}

impl Row {
    pub fn new(cells: Vec<String>) -> Row {
        Row { cells, style: None }
    }
    pub fn styled(cells: Vec<String>, style: Option<Style>) -> Row {
        Row { cells, style }
    }
}

pub struct Group {
    pub title: Option<String>,
    pub rows: Vec<Row>,
}

pub struct Table {
    pub columns: Vec<String>,
    pub rows: Vec<Row>,
    pub groups: Vec<Group>,
}

fn char_len(s: &str) -> usize {
    s.chars().count()
}

impl Table {
    pub fn new(columns: Vec<&str>) -> Table {
        Table {
            columns: columns.into_iter().map(|s| s.to_string()).collect(),
            rows: Vec::new(),
            groups: Vec::new(),
        }
    }

    pub fn add_row(&mut self, row: Row) {
        self.rows.push(row);
    }

    pub fn add_group(&mut self, group: Group) {
        self.groups.push(group);
    }

    fn column_widths(&self) -> Vec<usize> {
        let mut widths: Vec<usize> = self.columns.iter().map(|c| char_len(c)).collect();
        let all_rows = self.rows.iter().chain(self.groups.iter().flat_map(|g| g.rows.iter()));
        for row in all_rows {
            for (i, cell) in row.cells.iter().enumerate() {
                if i < widths.len() {
                    widths[i] = widths[i].max(char_len(cell));
                }
            }
        }
        widths
    }

    pub fn render(&self) -> String {
        let widths = self.column_widths();
        let term_width = crate::term::stdout_width();
        let widths = match term_width {
            Some(w) => shrink_widths(&widths, w, &self.columns),
            None => widths,
        };
        let mut out = String::new();
        write_cells(&mut out, &self.columns, &widths, Some("\x1b[4m"), term_width.is_some());
        out.push('\n');
        for row in &self.rows {
            write_cells(&mut out, &row.cells, &widths, row.style.map(|s| s.prefix()), term_width.is_some());
            out.push('\n');
        }
        for group in &self.groups {
            out.push('\n');
            if let Some(title) = &group.title {
                out.push_str("\x1b[1m");
                out.push_str(title);
                out.push_str("\x1b[0m");
                out.push('\n');
            }
            for row in &group.rows {
                write_cells(&mut out, &row.cells, &widths, row.style.map(|s| s.prefix()), term_width.is_some());
                out.push('\n');
            }
        }
        out
    }
}

/// Reduces the widths of the columns so that the table fits into the terminal.
fn shrink_widths(widths: &[usize], term_width: usize, _columns: &[String]) -> Vec<usize> {
    let available = term_width.saturating_sub(widths.len());
    let total: usize = widths.iter().sum();
    if total <= available || widths.is_empty() {
        return widths.to_vec();
    }
    let mut result = widths.to_vec();
    // shrink the widest columns first until everything fits
    loop {
        let total: usize = result.iter().sum();
        if total <= available {
            break;
        }
        let (idx, &max) = match result.iter().enumerate().max_by_key(|(_, w)| **w) {
            Some(x) => x,
            None => break,
        };
        if max <= 1 {
            break;
        }
        result[idx] = max - 1;
    }
    result
