fn is_whitespace(c: char) -> bool {
    c.is_whitespace() && c != NBSP
}

/// Splits a word at hyphens surrounded by alphanumeric characters.
/// Returns (head, tail) pairs, smallest head first, the last one being the whole word.
fn hyphen_splits(word: &str) -> Vec<(&str, &str)> {
    let mut triples = Vec::new();
    let mut char_indices = word.char_indices();
    let mut prev = match char_indices.next() {
        None => return vec![(word, "")],
        Some((_, ch)) => ch,
    };
    let (mut idx, mut cur) = match char_indices.next() {
        None => return vec![(word, "")],
        Some((idx, cur)) => (idx, cur),
    };
    for (i, next) in char_indices {
        if prev.is_alphanumeric() && cur == '-' && next.is_alphanumeric() {
            let (head, tail) = word.split_at(idx + 1);
            triples.push((head, tail));
        }
        prev = cur;
        idx = i;
        cur = next;
    }
    triples.push((word, ""));
    triples
}

struct WrapIter<'a> {
    source: &'a str,
    width: usize,
    chars: std::iter::Peekable<std::str::CharIndices<'a>>,
    start: usize,
    split: usize,
    split_len: usize,
    line_width: usize,
    line_width_at_split: usize,
    in_whitespace: bool,
    finished: bool,
}

impl<'a> WrapIter<'a> {
    fn new(source: &'a str, width: usize) -> WrapIter<'a> {
        WrapIter {
            source,
            width,
            chars: source.char_indices().peekable(),
            start: 0,
            split: 0,
            split_len: 0,
            line_width: 0,
            line_width_at_split: 0,
            in_whitespace: false,
            finished: false,
        }
    }
}

impl<'a> Iterator for WrapIter<'a> {
    type Item = String;

    fn next(&mut self) -> Option<String> {
        if self.finished {
            return None;
        }
        while let Some((idx, ch)) = self.chars.next() {
            if ch == '\x1b' {
                if let Some(&(_, '[')) = self.chars.peek() {
                    self.chars.next();
                    for (_, c) in self.chars.by_ref() {
                        if ('\x40'..='\x7e').contains(&c) {
                            break;
                        }
                    }
                    continue;
                }
            }
            let char_width = char_width(ch);
            let char_len = ch.len_utf8();
            if ch == '\n' {
                self.split = idx;
                self.split_len = char_len;
                self.line_width_at_split = self.line_width;
                self.in_whitespace = false;
                if self.split + self.split_len < self.source.len() {
                    let line = self.source[self.start..self.split].to_string();
                    self.start = self.split + self.split_len;
                    self.line_width = 0;
                    return Some(line);
                }
            } else if is_whitespace(ch) {
                if self.in_whitespace {
                    self.split_len += char_len;
                } else {
                    self.split = idx;
                    self.split_len = char_len;
                }
                self.line_width_at_split = self.line_width + char_width;
                self.in_whitespace = true;
            } else if self.line_width + char_width > self.width {
                self.in_whitespace = false;
                let remaining_text = &self.source[self.split + self.split_len..];
                let final_word = match remaining_text.find(is_whitespace) {
                    Some(i) => &remaining_text[..i],
                    None => remaining_text,
                };
                let splits = hyphen_splits(final_word);
                for &(head, _) in splits.iter().rev() {
                    if self.line_width_at_split + str_width(head) <= self.width {
                        self.split += self.split_len + head.len();
                        self.split_len = 0;
                        break;
                    }
                }
                if self.start >= self.split {
                    // the word is too long to fit: add smallest split
                    self.split = self.start + splits[0].0.len();
                    self.split_len = 0;
                    self.line_width_at_split = self.line_width;
                }
                if self.start < self.split {
                    let line = self.source[self.start..self.split].to_string();
                    self.start = self.split + self.split_len;
                    self.line_width -= self.line_width_at_split;
                    self.line_width += char_width;
                    self.line_width_at_split = 0;
                    return Some(line);
                }
            } else {
                self.in_whitespace = false;
            }
            self.line_width += char_width;
        }
        self.finished = true;
        if self.start < self.source.len() {
            return Some(self.source[self.start..].to_string());
        }
        None
    }
}

pub fn fill(s: &str, width: usize) -> String {
    let mut result = String::with_capacity(s.len());
    for (i, line) in WrapIter::new(s, width).enumerate() {
        if i > 0 {
            result.push('\n');
        }
        result.push_str(&line);
    }
    result
}

/// Wraps every line of the help text.
pub fn wrap_help(help: &str, avail_chars: usize) -> String {
    help.lines().map(|l| fill(l, avail_chars)).collect::<Vec<_>>().join("\n")
}
