pub enum Exit {
    Help(String),
    Version(String),
    Error(String),
}

impl Exit {
    pub fn exit(self) -> ! {
        use std::io::Write;
        match self {
            Exit::Help(s) | Exit::Version(s) => {
                let out = std::io::stdout();
                let mut out = out.lock();
                let _ = writeln!(out, "{}", s);
                let _ = out.flush();
                std::process::exit(0);
            }
            Exit::Error(s) => {
                eprintln!("{}", s);
                std::process::exit(1);
            }
        }
    }
}

