//! A small command line parser that mimics the behaviour (including the
//! help and error messages) of the argument parser used by bartib.

use crate::term;
use crate::textwrap::{str_width, wrap_help};
use std::collections::BTreeMap;

const TAB: &str = "    ";
const TERM_WIDTH: usize = 120;

#[derive(Clone)]
pub struct Arg {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub takes_value: bool,
    pub value_name: Option<&'static str>,
    pub help: &'static str,
    pub required: bool,
    pub default: Option<&'static str>,
    pub env: Option<(&'static str, Option<String>)>,
    pub blacklist: Vec<&'static str>,
    pub positional: bool,
    pub multiple: bool,
}

impl Arg {
    pub fn with_name(name: &'static str) -> Arg {
        Arg {
            name,
            short: None,
            long: None,
            takes_value: false,
            value_name: None,
            help: "",
            required: false,
            default: None,
            env: None,
            blacklist: Vec::new(),
            positional: false,
            multiple: false,
        }
    }
    pub fn short(mut self, c: char) -> Arg {
        self.short = Some(c);
        self
    }
    pub fn long(mut self, l: &'static str) -> Arg {
        self.long = Some(l);
        self
    }
    pub fn takes_value(mut self) -> Arg {
        self.takes_value = true;
        self
    }
    pub fn value_name(mut self, v: &'static str) -> Arg {
        self.value_name = Some(v);
        self.takes_value = true;
        self
    }
    pub fn help(mut self, h: &'static str) -> Arg {
        self.help = h;
        self
    }
    pub fn required(mut self) -> Arg {
        self.required = true;
        self
    }
    pub fn default_value(mut self, d: &'static str) -> Arg {
        self.default = Some(d);
        self.takes_value = true;
        self
    }
    pub fn env(mut self, name: &'static str) -> Arg {
        let val = std::env::var_os(name).map(|v| v.to_string_lossy().into_owned());
        self.env = Some((name, val));
        self.takes_value = true;
        self
    }
    pub fn conflicts_with_all(mut self, names: &[&'static str]) -> Arg {
        self.blacklist.extend_from_slice(names);
        self
    }
    pub fn positional(mut self) -> Arg {
        self.positional = true;
        self.takes_value = true;
        self
    }

    fn is_flag(&self) -> bool {
        !self.positional && !self.takes_value
    }
    fn is_opt(&self) -> bool {
        !self.positional && self.takes_value
    }
    fn has_switch(&self) -> bool {
        !self.positional
    }

    /// The textual representation used in usage strings and error messages.
    pub fn display(&self) -> String {
        if self.positional {
            let mut s = format!("<{}>", self.value_name.unwrap_or(self.name));
            if self.multiple {
                s.push_str("...");
            }
            s
        } else if self.takes_value {
            let mut s = match self.long {
                Some(l) => format!("--{} ", l),
                None => format!("-{} ", self.short.unwrap_or(' ')),
            };
            s.push_str(&format!("<{}>", self.value_name.unwrap_or(self.name)));
            if self.multiple {
                s.push_str("...");
            }
            s
        } else {
            match self.long {
                Some(l) => format!("--{}", l),
                None => format!("-{}", self.short.unwrap_or(' ')),
            }
        }
    }
}

#[derive(Clone)]
pub struct App {
    pub name: &'static str,
    pub bin_name: String,
    pub version: Option<&'static str>,
    pub author: Option<&'static str>,
    pub about: Option<&'static str>,
    pub after_help: Option<&'static str>,
    pub args: Vec<Arg>,
    pub subcommands: Vec<App>,
    pub subcommand_required_else_help: bool,
    pub help_flag_added: bool,
}

impl App {
    pub fn new(name: &'static str) -> App {
        App {
            name,
            bin_name: String::new(),
            version: None,
            author: None,
            about: None,
            after_help: None,
            args: Vec::new(),
            subcommands: Vec::new(),
            subcommand_required_else_help: false,
            help_flag_added: false,
        }
    }
    pub fn version(mut self, v: &'static str) -> App {
        self.version = Some(v);
        self
    }
    pub fn author(mut self, a: &'static str) -> App {
        self.author = Some(a);
        self
    }
    pub fn about(mut self, a: &'static str) -> App {
        self.about = Some(a);
        self
    }
    pub fn after_help(mut self, a: &'static str) -> App {
        self.after_help = Some(a);
        self
    }
    pub fn arg(mut self, a: Arg) -> App {
        self.args.push(a);
        self
    }
    pub fn subcommand(mut self, s: App) -> App {
        self.subcommands.push(s);
        self
    }
    pub fn subcommand_required_else_help(mut self) -> App {
        self.subcommand_required_else_help = true;
        self
    }

    /// Adds the automatically generated help (and version) flags and the
    /// help subcommand.
    fn create_help_and_version(&mut self) {
        if self.help_flag_added {
            return;
        }
        self.help_flag_added = true;
        self.args.push(
            Arg::with_name("help")
                .short('h')
                .long("help")
                .help("Prints help information"),
        );
        if self.version.is_some() {
            self.args.push(
                Arg::with_name("version")
                    .short('V')
                    .long("version")
                    .help("Prints version information"),
            );
        }
        if !self.subcommands.is_empty() && !self.subcommands.iter().any(|s| s.name == "help") {
            self.subcommands.push(
                App::new("help").about("Prints this message or the help of the given subcommand(s)"),
            );
        }
    }

    fn flags(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.is_flag())
    }
    fn opts(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.is_opt())
    }
    fn positionals(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.positional)
    }
    fn find(&self, name: &str) -> Option<&Arg> {
        self.args.iter().find(|a| a.name == name)
    }
    fn required(&self) -> Vec<&'static str> {
        self.args.iter().filter(|a| a.required).map(|a| a.name).collect()
    }
    fn longs(&self) -> Vec<&'static str> {
        self.flags().filter_map(|f| f.long).chain(self.opts().filter_map(|o| o.long)).collect()
    }
}

// ---------------------------------------------------------------------------
// Matches

#[derive(Clone, Default, Debug)]
pub struct MatchedArg {
    pub occurs: u32,
    pub vals: Vec<String>,
}

#[derive(Clone, Default, Debug)]
pub struct Matches {
    pub args: Vec<(&'static str, MatchedArg)>,
    pub subcommand: Option<(String, Box<Matches>)>,
}

impl Matches {
    fn get(&self, name: &str) -> Option<&MatchedArg> {
        self.args.iter().find(|(n, _)| *n == name).map(|(_, m)| m)
    }
    fn get_mut_or_insert(&mut self, name: &'static str) -> &mut MatchedArg {
        if let Some(pos) = self.args.iter().position(|(n, _)| *n == name) {
            &mut self.args[pos].1
        } else {
            self.args.push((name, MatchedArg::default()));
            let last = self.args.len() - 1;
            &mut self.args[last].1
        }
    }
    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
    fn inc_occurrence_of(&mut self, name: &'static str) {
        self.get_mut_or_insert(name).occurs += 1;
    }
    fn add_val_to(&mut self, name: &'static str, val: &str) {
        self.get_mut_or_insert(name).vals.push(val.to_string());
    }
    fn insert(&mut self, name: &'static str) {
        self.get_mut_or_insert(name);
    }
    fn names(&self) -> Vec<&'static str> {
        self.args.iter().map(|(n, _)| *n).collect()
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.get(name).and_then(|m| m.vals.first()).map(|s| s.as_str())
    }
    pub fn is_present(&self, name: &str) -> bool {
        self.contains(name)
    }
}

// ---------------------------------------------------------------------------
// Errors

pub enum Exit {
    Help(String),
    Version(String),
    Error(String),
}

impl Exit {
    pub fn exit(self) -> ! {
        use std::io::Write;
        match self {
            Exit::Help(s) | Exit::Version(s) => {
                let out = std::io::stdout();
                let mut out = out.lock();
                let _ = writeln!(out, "{}", s);
                let _ = out.flush();
                std::process::exit(0);
            }
            Exit::Error(s) => {
                eprintln!("{}", s);
                std::process::exit(1);
            }
        }
    }
}

struct Colorizer {
    enabled: bool,
}

impl Colorizer {
    fn new() -> Colorizer {
        let dumb = std::env::var("TERM").map(|t| t == "dumb").unwrap_or(false);
        Colorizer {
            enabled: term::stderr_is_tty() && !dumb,
        }
    }
    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn format_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

fn err_unknown_argument(arg: &str, did_you_mean: &str, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(arg),
        if did_you_mean.is_empty() {
            "\n".to_string()
        } else {
            format!("{}\n", did_you_mean)
        },
        usage,
        c.good("--help")
    ))
}

fn err_invalid_subcommand(subcmd: &str, did_you_mean: &str, name: &str, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} {} {}'\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(subcmd),
        c.good(did_you_mean),
        name,
        c.good("--"),
        subcmd,
        usage,
        c.good("--help")
    ))
}

fn err_unrecognized_subcommand(subcmd: &str, name: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The subcommand '{}' wasn't recognized\n\n{}\n\t{} help <subcommands>...\n\nFor more information try {}",
        c.error("error:"),
        c.warning(subcmd),
        c.warning("USAGE:"),
        name,
        c.good("--help")
    ))
}

fn err_empty_value(arg: &Arg, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(&arg.display()),
        usage,
        c.good("--help")
    ))
}

fn err_missing_required(required: &str, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        required,
        usage,
        c.good("--help")
    ))
}

fn err_unexpected_multiple_usage(arg: &Arg, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(&arg.display()),
        usage,
        c.good("--help")
    ))
}

fn err_argument_conflict(arg: &Arg, other: Option<String>, usage: &str) -> Exit {
    let c = Colorizer::new();
    Exit::Error(format!(
        "{} The argument '{}' cannot be used with {}\n\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(&arg.display()),
        match other {
            Some(n) => c.warning(&format!("'{}'", n)),
            None => "one or more of the other specified arguments".to_string(),
        },
        usage,
        c.good("--help")
    ))
}

// ---------------------------------------------------------------------------
// Suggestions

fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, a_char) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for (j, b_char) in b_chars.iter().enumerate().take(max_bound + 1) {
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|&(a_char, b_char)| a_char == b_char)
        .count();
    let jw = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean<'a>(v: &str, possible: &[&'a str]) -> Option<&'a str> {
    let mut candidate: Option<(f64, &'a str)> = None;
    for pv in possible {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|(_, c)| c)
}

fn did_you_mean_flag_suffix(arg: &str, args_rest: &[String], longs: &[&'static str], subcommands: &[App]) -> (String, Option<&'static str>) {
    if let Some(candidate) = did_you_mean(arg, longs) {
        let suffix = format!("\n\tDid you mean {}{}?", format_good("--"), format_good(candidate));
        return (suffix, Some(candidate));
    }
    let mut best: Option<(usize, (String, Option<&'static str>))> = None;
    for sc in subcommands {
        let opts = sc.longs();
        let candidate = match did_you_mean(arg, &opts) {
            Some(c) => c,
            None => continue,
        };
        let score = match args_rest.iter().position(|x| x == sc.name) {
            Some(s) => s,
            None => continue,
        };
        let suffix = format!(
            "\n\tDid you mean to put '{}{}' after the subcommand '{}'?",
            format_good("--"),
            format_good(candidate),
            format_good(sc.name)
        );
        match &best {
            Some((s, _)) if *s <= score => {}
            _ => best = Some((score, (suffix, Some(candidate)))),
        }
    }
    best.map(|(_, s)| s).unwrap_or_else(|| (String::new(), None))
}

// ---------------------------------------------------------------------------
// Usage strings

fn needs_flags_tag(app: &App) -> bool {
    app.flags().any(|f| !matches!(f.long, Some("help") | Some("version")))
}

fn get_required_usage_from(app: &App, reqs: &[&'static str], matcher: Option<&Matches>) -> Vec<String> {
    let mut desc_reqs: Vec<&'static str> = reqs.to_vec();
    desc_reqs.sort();
    desc_reqs.dedup();
    let mut ret = Vec::new();
    // positionals first, ordered by index
    let positional_names: Vec<&'static str> = app.positionals().map(|p| p.name).collect();
    for p in app.positionals() {
        if desc_reqs.contains(&p.name) {
            if let Some(m) = matcher {
                if m.contains(p.name) {
                    continue;
                }
            }
            ret.push(p.display());
        }
    }
    for name in desc_reqs.iter() {
        if positional_names.contains(name) {
            continue;
        }
        if let Some(m) = matcher {
            if m.contains(name) {
                continue;
            }
        }
        if let Some(a) = app.find(name) {
            ret.push(a.display());
        }
    }
    ret
}

fn get_args_tag(app: &App, incl_reqs: bool) -> Option<String> {
    let count = app.positionals().filter(|p| !p.required).count();
    if count > 1 {
        return None;
    } else if count == 1 && incl_reqs {
        let pos = app.positionals().find(|p| !p.required).unwrap();
        return Some(format!(
            " [{}]{}",
            pos.value_name.unwrap_or(pos.name),
            if pos.multiple { "..." } else { "" }
        ));
    }
    Some(String::new())
}

pub fn create_help_usage(app: &App, incl_reqs: bool) -> String {
    let mut usage = app.bin_name.clone();
    let req_string = if incl_reqs {
        let mut reqs = app.required();
        reqs.sort();
        reqs.dedup();
        get_required_usage_from(app, &reqs, None)
            .iter()
            .fold(String::new(), |a, s| a + &format!(" {}", s))
    } else {
        String::new()
    };
    if needs_flags_tag(app) {
        usage.push_str(" [FLAGS]");
    }
    if app.opts().any(|o| !o.required) {
        usage.push_str(" [OPTIONS]");
    }
    usage.push_str(&req_string);
    if app.positionals().any(|p| !p.required) {
        match get_args_tag(app, incl_reqs) {
            Some(tag) => usage.push_str(&tag),
            None => usage.push_str(" [ARGS]"),
        }
    }
    if !app.subcommands.is_empty() && incl_reqs {
        if app.subcommand_required_else_help {
            usage.push_str(" <SUBCOMMAND>");
        } else {
            usage.push_str(" [SUBCOMMAND]");
        }
    }
    usage
}

fn create_smart_usage(app: &App, used: &[&'static str]) -> String {
    let mut hs: Vec<&'static str> = app.required();
    hs.extend_from_slice(used);
    let r_string = get_required_usage_from(app, &hs, None)
        .iter()
        .fold(String::new(), |acc, s| acc + &format!(" {}", s));
    let mut usage = app.bin_name.clone();
    usage.push_str(&r_string);
    usage
}

fn create_usage_with_title(app: &App, used: &[&'static str]) -> String {
    let mut usage = String::from("USAGE:\n    ");
    if used.is_empty() {
        usage.push_str(&create_help_usage(app, true));
    } else {
        usage.push_str(&create_smart_usage(app, used));
    }
    usage
}

fn create_error_usage(app: &App, matcher: &Matches) -> String {
    let args: Vec<&'static str> = matcher
        .names()
        .into_iter()
        .filter(|n| match app.find(n) {
            Some(a) if a.positional => false,
            Some(a) if a.is_opt() => !a.required,
            _ => true,
        })
        .collect();
    create_usage_with_title(app, &args)
}

// ---------------------------------------------------------------------------
// Help

fn spec_vals(a: &Arg) -> String {
    let mut spec = Vec::new();
    if let Some((name, val)) = &a.env {
        spec.push(format!(" [env: {}={}]", name, val.as_deref().unwrap_or("")));
    }
    if let Some(d) = a.default {
        spec.push(format!(" [default: {}]", d));
    }
    spec.join(" ")
}

struct HelpWriter {
    out: String,
    longest: usize,
    force_next_line: bool,
}

impl HelpWriter {
    fn write_arg(&mut self, arg: &Arg) {
        // short
        self.out.push_str(TAB);
        if let Some(s) = arg.short {
            self.out.push('-');
            self.out.push(s);
        } else if arg.has_switch() {
            self.out.push_str(TAB);
        }
        // long
        if arg.has_switch() {
            if arg.takes_value {
                if let Some(l) = arg.long {
                    if arg.short.is_some() {
                        self.out.push_str(", ");
                    }
                    self.out.push_str("--");
                    self.out.push_str(l);
                }
                self.out.push(' ');
            } else if let Some(l) = arg.long {
                if arg.short.is_some() {
                    self.out.push_str(", ");
                }
                self.out.push_str("--");
                self.out.push_str(l);
            }
        }
        // val
        if arg.takes_value {
            if arg.has_switch() {
                self.out.push_str(&format!("<{}>", arg.value_name.unwrap_or(arg.name)));
                if arg.multiple {
                    self.out.push_str("...");
                }
            } else {
                self.out.push_str(&arg.display());
            }
        }
        let spec = spec_vals(arg);
        let h = arg.help;
        let h_w = str_width(h) + str_width(&spec);
        let taken = self.longest + 12;
        self.force_next_line =
            TERM_WIDTH >= taken && (taken as f32 / TERM_WIDTH as f32) > 0.40 && h_w > (TERM_WIDTH - taken);
        let self_len = str_width(&arg.display());
        if arg.has_switch() {
            if !self.force_next_line {
                let mut spcs = self.longest - self_len;
                if arg.long.is_some() {
                    spcs += 4;
                } else {
                    spcs += 8;
                }
                self.out.push_str(&" ".repeat(spcs));
            }
        } else if !self.force_next_line {
            self.out.push_str(&" ".repeat(self.longest + 4 - self_len));
        }
        self.write_help(h, &spec, arg.has_switch());
    }

    fn write_help(&mut self, h: &str, spec: &str, has_switch: bool) {
        let mut help = String::from(h) + spec;
        let spcs = if self.force_next_line { 12 } else { self.longest + 12 };
        let too_long = spcs + str_width(h) + str_width(spec) >= TERM_WIDTH;
        if self.force_next_line {
            self.out.push_str(&format!("\n{}{}{}", TAB, TAB, TAB));
        }
        if too_long && spcs <= TERM_WIDTH {
            let avail = TERM_WIDTH - spcs;
            help = wrap_help(&help, avail);
        }
        let mut lines = help.lines();
        if let Some(first) = lines.next() {
            self.out.push_str(first);
        }
        for part in lines {
            self.out.push('\n');
            if self.force_next_line {
                self.out.push_str(&format!("{}{}{}", TAB, TAB, TAB));
            } else if has_switch {
                self.out.push_str(&" ".repeat(self.longest + 12));
            } else {
                self.out.push_str(&" ".repeat(self.longest + 8));
            }
            self.out.push_str(part);
        }
        if !help.contains('\n') && self.force_next_line {
            self.out.push('\n');
        }
    }

    fn write_args(&mut self, args: Vec<&Arg>, sorted: bool) {
        self.longest = 2;
        for a in &args {
            let filter = if a.is_flag() { a.long.is_some() } else { true };
            if filter {
                self.longest = self.longest.max(str_width(&a.display()));
            }
        }
        let ordered: Vec<&Arg> = if sorted {
            let mut m: BTreeMap<&str, &Arg> = BTreeMap::new();
            for a in args {
                m.insert(a.name, a);
            }
            m.into_values().collect()
        } else {
            args
        };
        let mut first = true;
        for a in ordered {
            if !first {
                self.out.push('\n');
            }
            first = false;
            self.write_arg(a);
        }
    }

    fn write_subcommands(&mut self, app: &App) {
        self.longest = 2;
        let mut m: BTreeMap<&str, &App> = BTreeMap::new();
        for sc in &app.subcommands {
            self.longest = self.longest.max(str_width(sc.name));
            m.insert(sc.name, sc);
        }
        let mut first = true;
        for sc in m.values() {
            if !first {
                self.out.push('\n');
            }
            first = false;
            self.out.push_str(TAB);
            let h = sc.about.unwrap_or("");
            let taken = self.longest + 12;
            self.force_next_line =
                TERM_WIDTH >= taken && (taken as f32 / TERM_WIDTH as f32) > 0.40 && str_width(h) > (TERM_WIDTH - taken);
            self.out.push_str(sc.name);
            if !self.force_next_line {
                self.out.push_str(&" ".repeat(self.longest + 4 - str_width(sc.name)));
            }
            self.write_help(h, "", false);
        }
    }
}

pub fn write_help(app: &App) -> String {
    let mut w = HelpWriter {
        out: String::new(),
        longest: 2,
        force_next_line: false,
    };
    if app.bin_name.contains(' ') {
        w.out.push_str(&app.bin_name.replace(' ', "-"));
    } else {
        w.out.push_str(&wrap_help(app.name, TERM_WIDTH));
    }
    w.out.push(' ');
    w.out.push_str(app.version.unwrap_or(""));
    w.out.push('\n');
    if let Some(a) = app.author {
        w.out.push_str(&wrap_help(a, TERM_WIDTH));
        w.out.push('\n');
    }
    if let Some(a) = app.about {
        w.out.push_str(&wrap_help(a, TERM_WIDTH));
        w.out.push('\n');
    }
    w.out.push_str("\nUSAGE:");
    w.out.push_str(&format!("\n{}{}\n\n", TAB, create_help_usage(app, true)));

    let flags: Vec<&Arg> = app.flags().collect();
    let opts: Vec<&Arg> = app.opts().collect();
    let pos: Vec<&Arg> = app.positionals().collect();
    let has_sc = !app.subcommands.is_empty();
    let any = !flags.is_empty() || !opts.is_empty() || !pos.is_empty() || has_sc;
    let mut first = true;
    if !flags.is_empty() {
        w.out.push_str("FLAGS:\n");
        w.write_args(flags, true);
        first = false;
    }
    if !opts.is_empty() {
        if !first {
            w.out.push_str("\n\n");
        }
        w.out.push_str("OPTIONS:\n");
        w.write_args(opts, true);
        first = false;
    }
    if !pos.is_empty() {
        if !first {
            w.out.push_str("\n\n");
        }
        w.out.push_str("ARGS:\n");
        w.write_args(pos, false);
        first = false;
    }
    if has_sc {
        if !first {
            w.out.push_str("\n\n");
        }
        w.out.push_str("SUBCOMMANDS:\n");
        w.write_subcommands(app);
    }
    if let Some(h) = app.after_help {
        if any {
            w.out.push_str("\n\n");
        }
        if str_width(h) >= TERM_WIDTH {
            w.out.push_str(&wrap_help(h, TERM_WIDTH));
        } else {
            w.out.push_str(h);
        }
    }
    w.out
}

fn write_version(app: &App) -> String {
    let ver = app.version.unwrap_or("");
    if app.bin_name.contains(' ') {
        format!("{} {}", app.bin_name.replace(' ', "-"), ver)
    } else {
        format!("{} {}", app.name, ver)
    }
}

// ---------------------------------------------------------------------------
// Parsing

#[derive(Clone, Copy, PartialEq, Debug)]
enum ParseResult {
    Flag,
    Opt(&'static str),
    ValuesDone,
    NotFound,
}

struct Parser<'a> {
    app: &'a App,
    matcher: Matches,
}

impl<'a> Parser<'a> {
    fn is_new_arg(&self, arg: &str, needs_val_of: ParseResult) -> bool {
        if needs_val_of == ParseResult::ValuesDone {
            return true;
        }
        if arg.starts_with("--") {
            true
        } else if arg.starts_with('-') {
            arg.len() != 1
        } else {
            false
        }
    }

    fn add_val_to_arg(&mut self, arg: &Arg, val: &str) -> ParseResult {
        self.matcher.add_val_to(arg.name, val);
        if arg.multiple {
            ParseResult::Opt(arg.name)
        } else {
            ParseResult::ValuesDone
        }
    }

    fn parse_opt(&mut self, val: Option<&str>, opt: &Arg) -> ParseResult {
        let no_val = val.is_none();
        if let Some(fv) = val {
            let v = fv.trim_start_matches('=');
            self.add_val_to_arg(opt, v);
        }
        self.matcher.inc_occurrence_of(opt.name);
        if no_val || (opt.multiple && self.matcher.get(opt.name).is_some()) {
            return ParseResult::Opt(opt.name);
        }
        ParseResult::ValuesDone
    }

    fn help_exit(&self) -> Exit {
        Exit::Help(write_help(self.app))
    }

    fn version_exit(&self) -> Exit {
        Exit::Version(write_version(self.app))
    }

    fn parse_long_arg(&mut self, full_arg: &str, rest: &[String]) -> Result<ParseResult, Exit> {
        let trimmed = full_arg.trim_start_matches('-');
        let (arg, val) = if full_arg.contains('=') {
            let pos = trimmed.find('=').unwrap();
            (&trimmed[..pos], Some(&trimmed[pos..]))
        } else {
            (trimmed, None)
        };
        let app = self.app;
        if let Some(opt) = app.opts().find(|o| o.long == Some(arg)) {
            return Ok(self.parse_opt(val, opt));
        }
        if let Some(flag) = app.flags().find(|f| f.long == Some(arg)) {
            if arg == "help" {
                return Err(self.help_exit());
            }
            if arg == "version" && app.version.is_some() {
                return Err(self.version_exit());
            }
            self.matcher.inc_occurrence_of(flag.name);
            return Ok(ParseResult::Flag);
        }
        // didn't match anything
        let longs = app.longs();
        let suffix = did_you_mean_flag_suffix(arg, rest, &longs, &app.subcommands);
        if let Some(name) = suffix.1 {
            if let Some(opt) = app.opts().find(|o| o.long == Some(name)) {
                self.matcher.insert(opt.name);
            } else if let Some(flag) = app.flags().find(|f| f.long == Some(name)) {
                self.matcher.insert(flag.name);
            }
        }
        let used_arg = format!("--{}", arg);
        Err(err_unknown_argument(&used_arg, &suffix.0, &create_error_usage(app, &self.matcher)))
    }

    fn parse_short_arg(&mut self, full_arg: &str) -> Result<ParseResult, Exit> {
        let arg = full_arg.trim_start_matches('-');
        let app = self.app;
        let mut ret = ParseResult::NotFound;
        for (idx, c) in arg.char_indices() {
            if let Some(opt) = app.opts().find(|o| o.short == Some(c)) {
                let rest = &arg[idx + c.len_utf8()..];
                let val = if !rest.is_empty() { Some(rest) } else { None };
                return Ok(self.parse_opt(val, opt));
            } else if let Some(flag) = app.flags().find(|f| f.short == Some(c)) {
                if c == 'h' && flag.name == "help" {
                    return Err(self.help_exit());
                }
                if c == 'V' && flag.name == "version" {
                    return Err(self.version_exit());
                }
                self.matcher.inc_occurrence_of(flag.name);
                ret = ParseResult::Flag;
            } else {
                let a = format!("-{}", c);
                return Err(err_unknown_argument(&a, "", &create_error_usage(app, &self.matcher)));
            }
        }
        Ok(ret)
    }

    fn parse_help_subcommand(&self, cmds: &[String]) -> Exit {
        let root = self.app;
        let mut help_help = false;
        let mut bin_name = root.bin_name.clone();
        let mut sc: &App = root;
        for (i, cmd) in cmds.iter().enumerate() {
            if cmd == "help" {
                help_help = true;
            }
            if let Some(c) = sc.subcommands.iter().find(|s| s.name == cmd) {
                sc = c;
                if i == cmds.len() - 1 {
                    break;
                }
            } else {
                return err_unrecognized_subcommand(cmd, &root.bin_name);
            }
            bin_name = format!("{} {}", bin_name, sc.name);
        }
        let mut sc = sc.clone();
        if help_help {
            let mut pb = Arg::with_name("subcommand")
                .positional()
                .help("The subcommand whose help message to display");
            pb.multiple = true;
            sc.args.push(pb);
        } else {
            sc.create_help_and_version();
        }
        if sc.bin_name != root.bin_name || sc.bin_name.is_empty() {
            sc.bin_name = format!("{} {}", bin_name, sc.name);
        }
        if std::ptr::eq(root, &sc) {
            // never happens; keep borrowck happy
        }
        Exit::Help(write_help(&sc))
    }
}

fn get_matches_with(app: &App, args: &[String]) -> Result<Matches, Exit> {
    let mut app = app.clone();
    app.create_help_and_version();
    let app = &app;
    let mut p = Parser {
        app,
        matcher: Matches::default(),
    };
    let mut needs_val_of = ParseResult::NotFound;
    let mut pos_counter = 0usize;
    let positionals: Vec<&Arg> = app.positionals().collect();
    let mut trailing_values = false;
    let mut subcmd: Option<(usize, usize)> = None; // (subcommand index, next arg index)
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        let starts_new_arg = p.is_new_arg(arg, needs_val_of);
        if !trailing_values && arg == "--" && starts_new_arg {
            trailing_values = true;
            continue;
        }
        if !trailing_values {
            match needs_val_of {
                ParseResult::Opt(_) => {}
                _ => {
                    if let Some(idx) = app.subcommands.iter().position(|s| s.name == arg) {
                        if app.subcommands[idx].name == "help" {
                            return Err(p.parse_help_subcommand(&args[i..]));
                        }
                        subcmd = Some((idx, i));
                        break;
                    }
                }
            }
            if starts_new_arg {
                if arg.starts_with("--") {
                    needs_val_of = p.parse_long_arg(arg, &args[i..])?;
                    match needs_val_of {
                        ParseResult::Flag | ParseResult::Opt(_) | ParseResult::ValuesDone => continue,
                        _ => {}
                    }
                } else if arg.starts_with('-') && arg.len() != 1 {
                    needs_val_of = p.parse_short_arg(arg)?;
                    match needs_val_of {
                        ParseResult::Flag | ParseResult::Opt(_) | ParseResult::ValuesDone => continue,
                        _ => {}
                    }
                }
            } else if let ParseResult::Opt(name) = needs_val_of {
                let opt = app.find(name).unwrap();
                needs_val_of = p.add_val_to_arg(opt, arg);
                continue;
            }
        }

        let sc_names: Vec<&str> = app.subcommands.iter().map(|s| s.name).collect();
        if let Some(cdate) = did_you_mean(arg, &sc_names) {
            return Err(err_invalid_subcommand(
                arg,
                cdate,
                &app.bin_name,
                &create_error_usage(app, &p.matcher),
            ));
        }

        if let Some(pos) = positionals.get(pos_counter) {
            p.add_val_to_arg(pos, arg);
            p.matcher.inc_occurrence_of(pos.name);
            if !pos.multiple {
                pos_counter += 1;
            }
        } else {
            return Err(err_unknown_argument(arg, "", &create_error_usage(app, &p.matcher)));
        }
    }

    if let Some((idx, next)) = subcmd {
        let mut sc = app.subcommands[idx].clone();
        sc.bin_name = format!("{} {}", app.bin_name, sc.name);
        let sub_matches = get_matches_with(&sc, &args[next..])?;
        p.matcher.subcommand = Some((sc.name.to_string(), Box::new(sub_matches)));
    } else if app.subcommand_required_else_help {
        return Err(Exit::Error(write_help(app)));
    }

    validate(&mut p, needs_val_of)?;
    Ok(p.matcher)
}

fn validate(p: &mut Parser, needs_val_of: ParseResult) -> Result<(), Exit> {
    let app = p.app;
    // add env
    for a in app.opts().chain(app.positionals()) {
        if let Some((_, Some(val))) = &a.env {
            if p.matcher.get(a.name).map_or(true, |m| m.occurs == 0) {
                p.add_val_to_arg(a, val);
            }
        }
    }
    // add defaults
    for a in app.opts().chain(app.positionals()) {
        if let Some(d) = a.default {
            match p.matcher.get(a.name) {
                Some(m) if m.vals.is_empty() => {
                    p.add_val_to_arg(a, d);
                }
                Some(_) => {}
                None => {
                    p.add_val_to_arg(a, d);
                }
            }
        }
    }
    let mut reqs_validated = false;
    if let ParseResult::Opt(name) = needs_val_of {
        validate_required(p)?;
        reqs_validated = true;
        let should_err = match p.matcher.get(name) {
            Some(m) => m.vals.is_empty(),
            None => true,
        };
        if should_err {
            let o = app.find(name).unwrap();
            return Err(err_empty_value(o, &create_error_usage(app, &p.matcher)));
        }
    }
    validate_blacklist(p)?;
    if !reqs_validated {
        validate_required(p)?;
    }
    validate_matched_args(p)?;
    Ok(())
}

fn validate_required(p: &Parser) -> Result<(), Exit> {
    let app = p.app;
    let required = app.required();
    if required.iter().all(|r| p.matcher.contains(r)) {
        return Ok(());
    }
    let c = Colorizer::new();
    let mut reqs: Vec<&'static str> = required.into_iter().filter(|n| !p.matcher.contains(n)).collect();
    reqs.dedup();
    let req_args = get_required_usage_from(app, &reqs, Some(&p.matcher))
        .iter()
        .fold(String::new(), |acc, s| acc + &format!("\n    {}", c.error(s)));
    Err(err_missing_required(&req_args, &create_error_usage(app, &p.matcher)))
}

fn validate_blacklist(p: &Parser) -> Result<(), Exit> {
    let app = p.app;
    let mut conflicts: Vec<&'static str> = Vec::new();
    for name in p.matcher.names() {
        if let Some(arg) = app.find(name) {
            for conf in &arg.blacklist {
                if p.matcher.contains(conf) {
                    conflicts.push(conf);
                }
            }
        }
    }
    for name in conflicts {
        if let Some(ma) = p.matcher.get(name) {
            if ma.occurs > 0 {
                let mut c_with = None;
                for k in p.matcher.names() {
                    if let Some(a) = app.find(k) {
                        if a.blacklist.contains(&name) {
                            c_with = Some(a.display());
                        }
                    }
                }
                let usage = create_error_usage(app, &p.matcher);
                let arg = app.find(name).unwrap();
                return Err(err_argument_conflict(arg, c_with, &usage));
            }
        }
    }
    Ok(())
}

fn validate_matched_args(p: &Parser) -> Result<(), Exit> {
    let app = p.app;
    for (name, ma) in &p.matcher.args {
        let a = match app.find(name) {
            Some(a) => a,
            None => continue,
        };
        if a.takes_value && ma.vals.is_empty() {
            return Err(err_empty_value(a, &create_error_usage(app, &p.matcher)));
        }
        if ma.occurs > 1 && !a.multiple {
            return Err(err_unexpected_multiple_usage(a, &create_error_usage(app, &p.matcher)));
        }
    }
    Ok(())
}

pub fn get_matches(app: &App, args: &[String]) -> Result<Matches, Exit> {
    get_matches_with(app, args)
}
