//! Implementation of the sub commands.

use crate::activity::{self, Activity, Line};
use crate::cli::Matches;
use crate::table::{Group, Row, Style, Table};
use crate::time::{self, Date, DateTime, Duration};
use std::collections::{BTreeMap, BTreeSet, HashSet};

pub struct Error {
    pub message: String,
    pub cause: Option<String>,
}

impl Error {
    fn msg(m: &str) -> Error {
        Error {
            message: m.to_string(),
            cause: None,
        }
    }
    pub fn render(&self) -> String {
        match &self.cause {
            Some(c) => format!("Error: {}\n\nCaused by:\n    {}", self.message, c),
            None => format!("Error: {}", self.message),
        }
    }
}

impl From<activity::IoError> for Error {
    fn from(e: activity::IoError) -> Error {
        Error {
            message: e.context,
            cause: Some(e.error.to_string()),
        }
    }
}

type Result<T> = std::result::Result<T, Error>;

// ---------------------------------------------------------------------------
// argument helpers

fn get_time_argument_or_ignore(arg: Option<&str>, arg_name: &str) -> Option<DateTime> {
    let t = arg?;
    match time::parse_time(t) {
        Ok(secs) => {
            let today = time::today();
            Some(DateTime {
                secs: today.days * 86400 + secs,
                nanos: 0,
            })
        }
        Err(e) => {
            println!(
                "Can not parse \"{}\" as time. Argument for {} is ignored ({})",
                t,
                arg_name,
                e.message()
            );
            None
        }
    }
}

fn get_date_argument_or_ignore(arg: Option<&str>, arg_name: &str) -> Option<Date> {
    let d = arg?;
    match time::parse_date(d) {
        Ok(date) => Some(date),
        Err(e) => {
            println!(
                "Can not parse \"{}\" as date. Argument for {} is ignored ({})",
                d,
                arg_name,
                e.message()
            );
            None
        }
    }
}

fn get_number_argument_or_ignore(arg: Option<&str>, arg_name: &str) -> Option<usize> {
    let n = arg?;
    match n.parse::<usize>() {
        Ok(v) => Some(v),
        Err(_) => {
            println!("Can not parse \"{}\" as number. Argument for {} is ignored", n, arg_name);
            None
        }
    }
}

fn chrono_panic(msg: &str) -> ! {
    use std::io::Write;
    let _ = std::io::stdout().flush();
    eprintln!(
        "\nthread 'main' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/chrono-0.4.42/src/lib.rs:712:17:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        msg
    );
    std::process::exit(101);
}

const MAX_TIMEDELTA_SECS: i128 = 9_223_372_036_854_775;

/// Returns the rounding duration in seconds.
fn get_duration_argument_or_ignore(arg: Option<&str>, arg_name: &str) -> Option<i64> {
    let s = arg?;
    let (number, unit) = s.split_at(s.len().wrapping_sub(1));
    let n: i64 = number.parse().ok()?;
    match unit {
        "m" => {
            let secs = (n as i128) * 60;
            if secs.abs() > MAX_TIMEDELTA_SECS {
                chrono_panic("TimeDelta::minutes out of bounds");
            }
            Some(secs as i64)
        }
        "h" => {
            let secs = (n as i128) * 3600;
            if secs.abs() > MAX_TIMEDELTA_SECS {
                chrono_panic("TimeDelta::hours out of bounds");
            }
            Some(secs as i64)
        }
        _ => {
            println!("Can not parse \"{}\" as duration. Argument for {} is ignored", s, arg_name);
            None
        }
    }
}

#[derive(Default)]
struct Filter {
    from_date: Option<Date>,
    to_date: Option<Date>,
    date: Option<Date>,
    project: Option<String>,
}

impl Filter {
    fn matches(&self, a: &Activity) -> bool {
        let d = a.start.date();
        if let Some(date) = self.date {
            if d != date {
                return false;
            }
        } else {
            if let Some(f) = self.from_date {
                if d < f {
                    return false;
                }
            }
            if let Some(t) = self.to_date {
                if d > t {
                    return false;
                }
            }
        }
        if let Some(p) = &self.project {
            if &a.project != p {
                return false;
            }
        }
        true
    }
}

fn create_filter(m: &Matches) -> Filter {
    let mut filter = Filter {
        from_date: get_date_argument_or_ignore(m.value_of("from_date"), "--from"),
        to_date: get_date_argument_or_ignore(m.value_of("to_date"), "--to"),
        date: get_date_argument_or_ignore(m.value_of("date"), "-d/--date"),
        project: m.value_of("project").map(|s| s.to_string()),
    };
    let today = time::today();
    if m.is_present("today") {
        filter.date = Some(today);
    }
    if m.is_present("yesterday") {
        filter.date = Some(today.add_days(-1));
    }
    if m.is_present("current_week") {
        let monday = today.add_days(-today.weekday_from_monday());
        filter.from_date = Some(monday);
        filter.to_date = Some(monday.add_days(6));
    }
    if m.is_present("last_week") {
        let monday = today.add_days(-today.weekday_from_monday());
        filter.from_date = Some(monday.add_days(-7));
        filter.to_date = Some(monday.add_days(-1));
    }
    filter
}

fn round_activity(a: &Activity, round: Option<i64>) -> Activity {
    let mut a = a.clone();
    if let Some(r) = round {
        a.start = time::round_datetime(&a.start, r);
        a.end = a.end.map(|e| time::round_datetime(&e, r));
    }
    a
}

// ---------------------------------------------------------------------------

pub fn run(m: &Matches) -> Result<()> {
    let file_name = match m.value_of("file") {
        Some(f) => f.to_string(),
        None => {
            return Err(Error::msg(
                "Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable",
            ))
        }
    };
    let (name, sub) = match &m.subcommand {
        Some((n, s)) => (n.as_str(), s.as_ref()),
        None => return Ok(()),
    };
    match name {
        "start" => {
            let project = sub.value_of("project").unwrap_or("");
            let description = sub.value_of("description").unwrap_or("");
            let time = get_time_argument_or_ignore(sub.value_of("time"), "-t/--time");
            start(&file_name, project, description, time)
        }
        "continue" => {
            let project = sub.value_of("project");
            let description = sub.value_of("description");
            let time = get_time_argument_or_ignore(sub.value_of("time"), "-t/--time");
            let number = get_number_argument_or_ignore(sub.value_of("number"), "-n/--number").unwrap_or(0);
            continue_activity(&file_name, number, description, project, time)
        }
        "change" => {
            let project = sub.value_of("project");
            let description = sub.value_of("description");
            let time = get_time_argument_or_ignore(sub.value_of("time"), "-t/--time");
            change(&file_name, description, project, time)
        }
        "stop" => {
            let time = get_time_argument_or_ignore(sub.value_of("time"), "-t/--time");
            stop(&file_name, time)
        }
        "cancel" => cancel(&file_name),
        "current" => current(&file_name),
        "list" => {
            let number = get_number_argument_or_ignore(sub.value_of("number"), "-n/--number");
            let filter = create_filter(sub);
            let round = get_duration_argument_or_ignore(sub.value_of("round"), "--round");
            let do_group = !sub.is_present("no_grouping");
            list(&file_name, filter, do_group, number, round)
        }
        "report" => {
            let filter = create_filter(sub);
            let round = get_duration_argument_or_ignore(sub.value_of("round"), "--round");
            report(&file_name, filter, round)
        }
        "last" => {
            let number = get_number_argument_or_ignore(sub.value_of("number"), "-n/--number").unwrap_or(10);
            last(&file_name, number)
        }
        "projects" => projects(&file_name, sub.is_present("current"), sub.is_present("no-quotes")),
        "edit" => edit(&file_name, sub.value_of("editor")),
        "check" => check(&file_name),
        "sanity" => sanity(&file_name),
        "search" => search(&file_name, sub.value_of("search_term").unwrap_or("")),
        "status" => status(&file_name, sub.value_of("project")),
        _ => Ok(()),
    }
}

fn stop_all_running_activities(lines: &mut [Line], time: Option<DateTime>) {
    for line in lines.iter_mut() {
        if let Ok(a) = &mut line.activity {
            if !a.is_stopped() {
                a.stop(time);
                println!(
                    "Stopped activity: \"{}\" ({}) started at {} ({})",
                    a.description,
                    a.project,
                    a.start.format(),
                    time::format_duration(a.get_duration())
                );
                line.changed = true;
            }
        }
    }
}

fn start(file_name: &str, project: &str, description: &str, time: Option<DateTime>) -> Result<()> {
    let mut lines = activity::read_file(file_name).unwrap_or_default();
    stop_all_running_activities(&mut lines, time);
    let a = Activity::start(project, description, time);
    println!(
        "Started activity: \"{}\" ({}) at {}",
        a.description,
        a.project,
        a.start.format()
    );
    let n = lines.len() + 1;
    lines.push(Line::new_activity(a, n));
    activity::write_file(file_name, &lines)?;
    Ok(())
}

fn continue_activity(
    file_name: &str,
    number: usize,
    description: Option<&str>,
    project: Option<&str>,
    time: Option<DateTime>,
) -> Result<()> {
    let mut lines = activity::read_file(file_name)?;
    let distinct = activity::get_descriptions_and_projects(&lines);
    if distinct.is_empty() {
        return Err(Error::msg("No activity has been started before."));
    }
    if number > distinct.len() {
        return Err(Error::msg(&format!(
            "Less than {} distinct activities have been logged yet",
            number
        )));
    }
    let idx = std::cmp::min(number, distinct.len() - 1);
    let (d, p) = distinct[idx].clone();
    let new_description = description.map(|s| s.to_string()).unwrap_or(d);
    let new_project = project.map(|s| s.to_string()).unwrap_or(p);
    stop_all_running_activities(&mut lines, time);
    let a = Activity::start(&new_project, &new_description, time);
    println!(
        "Started activity: \"{}\" ({}) at {}",
        a.description,
        a.project,
        a.start.format()
    );
    let n = lines.len() + 1;
    lines.push(Line::new_activity(a, n));
    activity::write_file(file_name, &lines)?;
    Ok(())
}

fn change(file_name: &str, description: Option<&str>, project: Option<&str>, time: Option<DateTime>) -> Result<()> {
    let mut lines = activity::read_file(file_name)?;
    for line in lines.iter_mut() {
        if let Ok(a) = &mut line.activity {
            if !a.is_stopped() {
                let mut changed = false;
                if let Some(d) = description {
                    a.description = d.to_string();
                    changed = true;
                }
                if let Some(p) = project {
                    a.project = p.to_string();
                    changed = true;
                }
                if let Some(t) = time {
                    a.start = t;
                    changed = true;
                }
                if changed {
                    println!(
                        "Changed activity: \"{}\" ({}) started at {}",
                        a.description,
                        a.project,
                        a.start.format()
                    );
                    line.changed = true;
                }
            }
        }
    }
    activity::write_file(file_name, &lines)?;
    Ok(())
}

fn stop(file_name: &str, time: Option<DateTime>) -> Result<()> {
    let mut lines = activity::read_file(file_name)?;
    stop_all_running_activities(&mut lines, time);
    activity::write_file(file_name, &lines)?;
    Ok(())
}

fn cancel(file_name: &str) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let mut new_lines = Vec::new();
    for line in lines {
        if let Ok(a) = &line.activity {
            if !a.is_stopped() {
                println!(
                    "Canceled activity: \"{}\" ({}) started at {}",
                    a.description,
                    a.project,
                    a.start.format()
                );
                continue;
            }
        }
        new_lines.push(line);
    }
    activity::write_file(file_name, &new_lines)?;
    Ok(())
}

fn current(file_name: &str) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let activities = activity::get_activities(&lines);
    let running: Vec<&Activity> = activities
        .iter()
        .map(|(_, a)| *a)
        .filter(|a| !a.is_stopped())
        .collect();
    if running.is_empty() {
        println!("No Activity is currently running");
        return Ok(());
    }
    let mut table = Table::new(vec!["Started At", "Description", "Project", "Duration"]);
    for a in running {
        table.add_row(Row::new(vec![
            a.start.format(),
            a.description.clone(),
            a.project.clone(),
            time::format_duration(a.get_duration()),
        ]));
    }
    println!("\n{}", table.render());
    Ok(())
}

fn activity_row(a: &Activity, with_start_dates: bool) -> Row {
    let start = if with_start_dates {
        a.start.format()
    } else {
        a.start.format_time()
    };
    let end = match a.end {
        None => "-".to_string(),
        Some(e) => {
            if e.date() == a.start.date() {
                e.format_time()
            } else {
                e.format()
            }
        }
    };
    let style = match a.end {
        None => Some(Style::Green),
        Some(e) if e.date() != a.start.date() => Some(Style::Yellow),
        _ => None,
    };
    Row::styled(
        vec![
            start,
            end,
            a.description.clone(),
            a.project.clone(),
            time::format_duration(a.get_duration()),
        ],
        style,
    )
}

fn list(file_name: &str, filter: Filter, do_group: bool, number: Option<usize>, round: Option<i64>) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let activities = activity::get_activities(&lines);
    let mut filtered: Vec<Activity> = activities
        .iter()
        .map(|(_, a)| round_activity(a, round))
        .filter(|a| filter.matches(a))
        .collect();
    filtered.sort_by_key(|a| a.start);
    let first = match number {
        Some(n) => filtered.len().saturating_sub(n),
        None => 0,
    };
    let shown = &filtered[first..];
    if shown.is_empty() {
        println!("No activity to display");
        return Ok(());
    }
    let columns = vec!["Started", "Stopped", "Description", "Project", "Duration"];
    let mut table = Table::new(columns);
    if filter.date.is_some() {
        for a in shown {
            table.add_row(activity_row(a, false));
        }
    } else if !do_group {
        for a in shown {
            table.add_row(activity_row(a, true));
        }
    } else {
        let mut groups: BTreeMap<Date, Vec<&Activity>> = BTreeMap::new();
        for a in shown {
            groups.entry(a.start.date()).or_default().push(a);
        }
        for (date, acts) in groups {
            let total: Duration = acts.iter().map(|a| a.get_duration()).sum();
            let title = format!("{}\t{}", date.format(), time::format_duration(total));
            let rows = acts.iter().map(|a| activity_row(a, false)).collect();
            table.add_group(Group {
                title: Some(title),
                rows,
            });
        }
    }
    println!("\n{}", table.render());
    Ok(())
}

fn report(file_name: &str, filter: Filter, round: Option<i64>) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let activities = activity::get_activities(&lines);
    let mut filtered: Vec<Activity> = activities
        .iter()
        .map(|(_, a)| round_activity(a, round))
        .filter(|a| filter.matches(a))
        .collect();
    filtered.sort_by_key(|a| a.start);

    let mut projects: BTreeMap<String, (BTreeMap<String, Duration>, Duration)> = BTreeMap::new();
    let mut total: Duration = 0;
    for a in &filtered {
        let d = a.get_duration();
        let entry = projects.entry(a.project.clone()).or_default();
        *entry.0.entry(a.description.clone()).or_default() += d;
        entry.1 += d;
        total += d;
    }
    let mut longest_line = 0usize;
    let mut longest_duration = time::format_duration(total).chars().count();
    for (p, (descs, d)) in &projects {
        longest_line = longest_line.max(p.chars().count());
        longest_duration = longest_duration.max(time::format_duration(*d).chars().count());
        for (desc, dd) in descs {
            longest_line = longest_line.max(desc.chars().count() + 4);
            longest_duration = longest_duration.max(time::format_duration(*dd).chars().count());
        }
    }
    let mut out = String::new();
    out.push('\n');
    for (p, (descs, d)) in &projects {
        out.push_str(&format!(
            "\x1b[1m{:.<w$} {:>dw$}\x1b[0m\n",
            p,
            time::format_duration(*d),
            w = longest_line,
            dw = longest_duration
        ));
        for (desc, dd) in descs {
            out.push_str(&format!(
                "    {:.<w$} {:>dw$}\n",
                desc,
                time::format_duration(*dd),
                w = longest_line.saturating_sub(4),
                dw = longest_duration
            ));
        }
        out.push('\n');
    }
    out.push_str(&format!(
        "\x1b[1m{:.<w$} {}\x1b[0m\n",
        "Total",
        time::format_duration(total),
        w = longest_line
    ));
    println!("{}", out);
    Ok(())
}

fn last(file_name: &str, number: usize) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let distinct = activity::get_descriptions_and_projects(&lines);
    let shown: Vec<(usize, &(String, String))> = distinct.iter().enumerate().take(number).collect();
    if shown.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
    let mut table = Table::new(vec![" #", "Description", "Project"]);
    for (i, (d, p)) in shown.iter().rev() {
        table.add_row(Row::new(vec![format!("[{}]", i), d.clone(), p.clone()]));
    }
    println!("\n{}", table.render());
    Ok(())
}

fn search(file_name: &str, term: &str) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let distinct = activity::get_descriptions_and_projects(&lines);
    let term = term.to_lowercase();
    let found: Vec<(usize, &(String, String))> = distinct
        .iter()
        .enumerate()
        .filter(|(_, (d, p))| d.to_lowercase().contains(&term) || p.to_lowercase().contains(&term))
        .collect();
    if found.is_empty() {
        println!("No matching activities found");
        return Ok(());
    }
    let mut table = Table::new(vec![" #", "Description", "Project"]);
    for (i, (d, p)) in found.iter().rev() {
        table.add_row(Row::new(vec![format!("[{}]", i), d.clone(), p.clone()]));
    }
    println!("\n{}", table.render());
    Ok(())
}

fn projects(file_name: &str, current_only: bool, no_quotes: bool) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let activities = activity::get_activities(&lines);
    let mut set: BTreeSet<&str> = BTreeSet::new();
    for (_, a) in &activities {
        if current_only && a.is_stopped() {
            continue;
        }
        set.insert(a.project.as_str());
    }
    for p in set {
        if no_quotes {
            println!("{}", p);
        } else {
            println!("\"{}\"", p);
        }
    }
    Ok(())
}

fn edit(file_name: &str, editor: Option<&str>) -> Result<()> {
    let editor = match editor {
        Some(e) => e,
        None => return Err(Error::msg("editor command is missing")),
    };
    let mut child = std::process::Command::new(editor)
        .arg(file_name)
        .spawn()
        .map_err(|e| Error::msg(&e.to_string()))?;
    child.wait().map_err(|e| Error::msg(&e.to_string()))?;
    Ok(())
}

fn check(file_name: &str) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let errors: Vec<&Line> = lines.iter().filter(|l| l.activity.is_err()).collect();
    if errors.is_empty() {
        println!("All lines in the file have been successfully parsed as activities.");
        return Ok(());
    }
    println!("Found {} line(s) with parsing errors", errors.len());
    for l in errors {
        if let Err(e) = &l.activity {
            println!("\n{}\n  -> {} (Line: {})", l.text, e.message(), l.number);
        }
    }
    Ok(())
}

fn sanity(file_name: &str) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let mut activities = activity::get_activities_silent(&lines);
    activities.sort_by_key(|(_, a)| a.start);
    let mut max_end: Option<DateTime> = None;
    let mut problems: Vec<(usize, &Activity, Vec<&str>)> = Vec::new();
    for (n, a) in activities {
        let mut p = Vec::new();
        if a.get_duration() < 0 {
            p.push("Activity has negative duration");
        }
        if let Some(me) = max_end {
            if a.start < me {
                p.push("Activity started before another activity ended");
            }
        }
        if let Some(e) = a.end {
            max_end = Some(match max_end {
                Some(me) if me > e => me,
                _ => e,
            });
        }
        if !p.is_empty() {
            problems.push((n, a, p));
        }
    }
    if problems.is_empty() {
        println!("No unusual activities.");
        return Ok(());
    }
    for (n, a, ps) in problems {
        for p in ps {
            println!("{}", p);
        }
        println!(
            "{} (Started: {}, Ended: {}, Line: {})",
            a.description,
            a.start.format(),
            a.end.map(|e| e.format()).unwrap_or_else(|| "--".to_string()),
            n
        );
        println!();
    }
    Ok(())
}

fn paint(codes: &str, s: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", codes, s)
}

fn status(file_name: &str, project: Option<&str>) -> Result<()> {
    let lines = activity::read_file(file_name)?;
    let activities = activity::get_activities(&lines);
    let filtered: Vec<&Activity> = activities
        .iter()
        .map(|(_, a)| *a)
        .filter(|a| project.map_or(true, |p| a.project == p))
        .collect();
    let mut running: Vec<&Activity> = filtered.iter().copied().filter(|a| !a.is_stopped()).collect();
    running.sort_by_key(|a| a.start);

    let today = time::today();
    let monday = today.add_days(-today.weekday_from_monday());
    let first_of_month = today.first_of_month();
    let sum = |from: Date, to: Date| -> Duration {
        filtered
            .iter()
            .filter(|a| {
                let d = a.start.date();
                d >= from && d <= to
            })
            .map(|a| a.get_duration())
            .sum()
    };

    let mut out = String::new();
    match project {
        Some(p) => {
            out.push_str(&paint("2", "\n ======="));
            out.push_str(&paint("3", " Status for project: "));
            out.push_str(&paint("1", p));
            out.push_str(&paint("2", " ======= \n"));
        }
        None => {
            out.push_str(&paint("2", "\n ======="));
            out.push_str(&paint("3", " Status for "));
            out.push_str(&paint("1", "ALL"));
            out.push_str(&paint("3", " projects "));
            out.push_str(&paint("2", " ======= \n"));
        }
    }
    out.push_str(&paint("2;3", "\n  NOW: "));
    match running.first() {
        Some(a) => {
            out.push_str(&paint("1;32", &a.description));
            if project.is_none() {
                out.push_str(&paint("2;3", " on "));
                out.push_str(&paint("3", &a.project));
            }
            out.push_str(&paint("2", " ...... "));
            out.push_str(&paint("1", &time::format_duration(a.get_duration())));
            out.push_str(&paint("2", "\n\n"));
        }
        None => {
            out.push_str(&paint("1", " NO Activity\n\n"));
        }
    }
    let rows = [
        ("Today", sum(today, today)),
        ("Current week", sum(monday, today)),
        ("Current month", sum(first_of_month, today)),
    ];
    for (label, d) in rows.iter() {
        out.push_str(&paint("3", " "));
        out.push_str(&paint("2;3", &format!(" {:.<30} ", label)));
        out.push_str(&paint("1", &time::format_duration(*d)));
        out.push_str(&paint("3", "\n"));
    }
    println!("{}", out);
    Ok(())
}

