        return widths.to_vec();
    }
    let mut result = widths.to_vec();
    loop {
        let total: usize = result.iter().sum();
        if total as i64 <= available {
            break;
        }
        let mut best: Option<usize> = None;
        for (i, w) in result.iter().enumerate() {
            if !wrap.get(i).copied().unwrap_or(false) {
                continue;
            }
