/// Reduces the widths of the wrappable columns so that the table fits into
/// the terminal.
fn shrink_widths(widths: &[usize], wrap: &[bool], term_width: usize) -> Vec<usize> {
    let available = term_width as i64 - widths.len() as i64;
    let fixed: usize = widths
        .iter()
        .enumerate()
        .filter(|(i, _)| !wrap.get(*i).copied().unwrap_or(false))
        .map(|(_, w)| *w)
        .sum();
    if fixed as i64 > available {
        return widths.to_vec();
    }
    let mut result = widths.to_vec();
    loop {
        let total: usize = result.iter().sum();
        if total as i64 <= available {
            break;
        }
        let mut best: Option<usize> = None;
        for (i, w) in result.iter().enumerate() {
            if !wrap.get(i).copied().unwrap_or(false) {
                continue;
            }
            match best {
                Some(b) if result[b] > *w => {}
                _ => best = Some(i),
            }
        }
        match best {
            Some(b) if result[b] > 1 => result[b] -= 1,
            _ => break,
        }
    }
    result
}
